      def status_code_family(code)
        @protocol_workspace ||= {}
        family = case code.to_i / 100
                 when 1 then :information
                 when 2 then :successful
                 when 3 then :redirect
                 when 4 then :client_error
                 when 5 then :server_error
                 else :unknown
                 end
        @protocol_workspace[:resolved_family] = family
        family
      end

      def numeric_bounds_snapshot(from, to)
        @network_workspace ||= {}
        lower = from
        upper = to
        swapped = false
        if upper < lower
          lower, upper = upper, lower
          swapped = true
        end
        snapshot = { lower: lower, upper: upper, swapped: swapped }
        @network_workspace[:numeric_bounds] = snapshot
        snapshot
      end

