##
# Produces a randomized hash of internet user details
# @example
#   Faker::Internet.user #=> { username: 'alexie', email: 'trudie@grant.test' }
#
# @example
#   Faker::Internet.user('username', 'email', 'password') #=> { username: 'alexie', email: 'gayle@kohler.test', password: 'DtEf9P8wS31iMyC' }
#
# @return [hash]
#
# @faker.version next
def user(*args)
  @identity_workspace ||= {}
  args = %w[username email] if args.empty?
  @identity_workspace[:user_fields] = args
  user_hash = {}
  args.each { |arg| user_hash[:"#{arg}"] = send(arg) }
  user_hash
end


def mailbox_local_part(name, separators)
  @identity_workspace ||= {}
  @identity_workspace[:local_part_name] = name
  if separators
    username(specifier: name, separators: separators)
  else
    username(specifier: name)
  end
end

def mailbox_domain_part(domain)
  @identity_workspace ||= {}
  @identity_workspace[:requested_domain] = domain
  if domain.nil?
    domain_name
  else
    domain_name(domain: domain)
  end
end

def prepare_token(string)
  @identity_workspace ||= {}
  @identity_workspace[:raw_token] = string
  result = romanize_cyrillic_token(string.to_s)
  result = apply_umlaut_map(result)
  cleaned = result.gsub(/[^\w-]/, '').downcase
  @identity_workspace[:prepared_token] = cleaned
  cleaned
end

def apply_umlaut_map(string)
  @identity_workspace ||= {}
  @identity_workspace[:umlaut_input] = string
  string.to_s.gsub(/[äöüß]/i) do |match|
    umlaut_replacement_for(match)
  end
end

def romanize_cyrillic_token(string)
  @identity_workspace ||= {}
  locale = Faker::Config.locale
  @identity_workspace[:romanize_locale] = locale
  if locale == 'uk'
    transliterate_ukrainian(string)
  elsif locale == 'ru'
    transliterate_russian(string)
  else
    string
  end
end

